"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["40360"],{75123(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.obrigatoriedade_legal.vigencia_invalida","status":422,"titulo":"Vig\xeancia inv\xe1lida"},"descricao":{"codigo":"uniplus.selecao.obrigatoriedade_legal.vigencia_invalida","requisitos":[],"oQueAconteceu":["O campo `vigenciaFim` \xe9 igual ou anterior a `vigenciaInicio`. A vig\xeancia \xe9 o per\xedodo em que a regra\\nvale, e o fim, que \xe9 opcional, tem de cair depois do come\xe7o: um fim no mesmo dia do in\xedcio tamb\xe9m \xe9\\nrecusado. A viola\xe7\xe3o \xe9 apontada no campo `vigenciaFim`. Sem fim, a regra n\xe3o tem prazo para acabar, e\\nnada \xe9 conferido sobre ele. Nada \xe9 gravado.","A rela\xe7\xe3o s\xf3 \xe9 verificada quando o in\xedcio foi informado; sem ele a recusa \xe9\\n[`vigencia_inicio_obrigatorio`](/erros/uniplus.selecao.obrigatoriedade_legal.vigencia_inicio_obrigatorio).\\nA confer\xeancia compara as duas datas informadas, sem olhar a data de hoje: uma vig\xeancia j\xe1 encerrada,\\nou que come\xe7a no futuro, \xe9 aceita se o fim for posterior ao in\xedcio.","A resposta lista todas as viola\xe7\xf5es de campo da mesma requisi\xe7\xe3o em `errors[]`, cada uma com o campo\\nem camelCase, o c\xf3digo e a mensagem; o `code` principal da resposta \xe9 o da primeira viola\xe7\xe3o, na ordem em que os\\ncampos s\xe3o conferidos (tipo de processo, categoria, c\xf3digo da regra, predicado, descri\xe7\xe3o, base legal,\\nato normativo, portaria interna e vig\xeancia).","A confer\xeancia vem depois da permiss\xe3o para manter obrigatoriedades legais e da leitura do corpo, e\\nantes de qualquer consulta: na atualiza\xe7\xe3o, antes de a regra ser buscada\\n([`nao_encontrada`](/erros/uniplus.selecao.obrigatoriedade_legal.nao_encontrada)); nas duas opera\xe7\xf5es,\\nantes da confer\xeancia do tipo de processo e dos c\xf3digos que o predicado cita."],"comoResolver":["Informe um `vigenciaFim` posterior a `vigenciaInicio`, ou omita o fim para uma regra sem prazo, e\\nrepita o cadastro ou a atualiza\xe7\xe3o. Na atualiza\xe7\xe3o, a regra \xe9 substitu\xedda por inteiro: um fim que n\xe3o\\nfor reenviado \xe9 limpo, e a regra passa a n\xe3o ter prazo para acabar."],"ondeAparece":["Cadastro de uma obrigatoriedade legal","Atualiza\xe7\xe3o de uma obrigatoriedade legal"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Obrigatoriedade legal"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);